import type { ChangeToken } from "#types";

/**
 * Geeft de waarde van een omgevingsvariabele, of gooit een fout als deze niet gezet is.
 * @param key Naam van de omgevingsvariabele
 */
export function requireEnv(key: string): string {
    const value = process.env[key];
    if (!value) throw new Error(`${key} is not defined.`);
    return value;
}

/**
 * @returns Opgemaakte timestamp van huidig tijdstip, wat gebruikt kan worden als changetoken in Axon
 */
export function getFormattedTimestamp() {
    const now = new Date();
    const pad = (n: number) => String(n).padStart(2, '0');

    const datePart = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
    const timePart = `${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`;

    return `${datePart} ${timePart}.000000` as ChangeToken;
}